"""Exact finite-domain compiler for the telemetry rule protocol.

The implementation deliberately works on the declared finite Cartesian universe.
Predicate truth is represented by Python integer bitsets: training windows use bit
position = training index, world windows use bit position = mixed-radix universe
index.  This makes the three discovery conditions (coverage, literal necessity and
non-tautology) direct exact operations.
"""
from __future__ import annotations

from itertools import product
from math import prod


# ---------------------------------------------------------------------------
# Compile the protocol's terms and predicates to compact evaluator records.
# ---------------------------------------------------------------------------

def _compile_term(term, names, nf):
    if "const" in term:
        return ("const", term["const"])
    if "sum" in term:
        return (
            "sum",
            tuple(ref[0] * nf + names[ref[1]] for ref in term["sum"]),
        )
    if "scale" in term:
        ref = term["ref"]
        return ("scale", term["scale"], ref[0] * nf + names[ref[1]])
    ref = term["ref"]
    return ("ref", ref[0] * nf + names[ref[1]])


def _compile_predicate(pred, names, nf, slots):
    if pred["kind"] == "cmp":
        return (
            "cmp",
            pred["op"],
            _compile_term(pred["left"], names, nf),
            _compile_term(pred["right"], names, nf),
        )
    field_ordinal = names[pred["field"]]
    positions = tuple(slot * nf + field_ordinal for slot in range(slots))
    return (pred["kind"], positions, pred["op"], pred["value"])


def _term_value(term, row):
    kind = term[0]
    if kind == "ref":
        return row[term[1]]
    if kind == "const":
        return term[1]
    if kind == "sum":
        total = 0
        for pos in term[1]:
            total += row[pos]
        return total
    # scale
    return term[1] * row[term[2]]


def _compare(left, op, right):
    if op == "eq":
        return left == right
    if op == "ne":
        return left != right
    if op == "lt":
        return left < right
    if op == "le":
        return left <= right
    if op == "gt":
        return left > right
    # ge
    return left >= right


def _predicate_true(pred, row):
    kind = pred[0]
    if kind == "cmp":
        return _compare(
            _term_value(pred[2], row), pred[1], _term_value(pred[3], row)
        )

    # Quantified any/all predicate.  ``positions`` has one entry per slot.
    op = pred[2]
    value = pred[3]
    if kind == "any":
        for pos in pred[1]:
            if _compare(row[pos], op, value):
                return True
        return False
    # all
    for pos in pred[1]:
        if not _compare(row[pos], op, value):
            return False
    return True


# ---------------------------------------------------------------------------
# Bitset construction.
# ---------------------------------------------------------------------------

def _truth_masks(rows, predicates):
    """Return one little-endian integer bitmask per predicate."""
    row_count = len(rows)
    byte_count = (row_count + 7) // 8
    chunks = [bytearray(byte_count) for _ in predicates]
    true_test = _predicate_true
    for index, row in enumerate(rows):
        byte_index = index >> 3
        bit = 1 << (index & 7)
        for p_index, pred in enumerate(predicates):
            if true_test(pred, row):
                chunks[p_index][byte_index] |= bit
    return [int.from_bytes(chunk, "little") for chunk in chunks]


def _lowest_set_bit_index(bits):
    return (bits & -bits).bit_length() - 1


def _all_ones(count):
    return (1 << count) - 1


# ---------------------------------------------------------------------------
# Exact discovery.
# ---------------------------------------------------------------------------

def _discover_rules(predicate_count, width, train_masks, world_masks,
                    train_count, world_count):
    """Enumerate every eligible clause and its two deterministic certificates.

    A clause is a disjunction.  Coverage over all training rows is monotone as
    literals are added, so recursive enumeration stops extending a clause as soon
    as its partial disjunction already covers every training row.  Such an
    extension can never satisfy literal-by-literal inclusion minimality.
    """
    all_training = _all_ones(train_count)
    all_worlds = _all_ones(world_count)
    max_len = min(width, predicate_count)
    rules = []
    empty = ()

    def examine(clause, covered):
        witnesses = []
        for literal in clause:
            others = 0
            for other in clause:
                if other != literal:
                    others |= train_masks[other]
            only_this = train_masks[literal] & ~others & all_training
            # ``covered == all_training`` ensures this is exactly condition 2;
            # nonetheless checking the bitmask is the canonical witness rule.
            if not only_this:
                return
            witnesses.append(_lowest_set_bit_index(only_this))

        world_union = 0
        for literal in clause:
            world_union |= world_masks[literal]
        falsifying = all_worlds & ~world_union
        if not falsifying:              # a domain tautology
            return

        rules.append({
            "clause": list(clause),
            "witnesses": witnesses,
            "counterexample": _lowest_set_bit_index(falsifying),
        })

    def extend(start, clause, covered):
        # No clause of this prefix can be extended to one of valid length.
        if len(clause) == max_len:
            return
        for literal in range(start, predicate_count):
            next_clause = clause + (literal,)
            next_covered = covered | train_masks[literal]
            if next_covered == all_training:
                examine(next_clause, next_covered)
                # Adding literals cannot repair inclusion minimality once a
                # proper prefix already covers every training window.
            else:
                extend(literal + 1, next_clause, next_covered)

    extend(0, empty, 0)
    rules.sort(key=lambda rule: (len(rule["clause"]), tuple(rule["clause"])))
    return rules


# ---------------------------------------------------------------------------
# Decoding helpers.
# ---------------------------------------------------------------------------

def _fixed_value_masks(worlds, needed_values):
    """Build world bitsets only for the (coordinate,value) pairs actually used.

    Target prefixes are evaluated while walking completions, so unlike a naive
    table this never allocates one full bitset for every domain value.
    """
    world_count = len(worlds)
    byte_count = (world_count + 7) // 8
    result = {}
    for position, values in needed_values.items():
        chunks = {value: bytearray(byte_count) for value in values}
        get_chunk = chunks.get
        for index, row in enumerate(worlds):
            chunk = get_chunk(row[position])
            if chunk is not None:
                chunk[index >> 3] |= 1 << (index & 7)
        for value, chunk in chunks.items():
            result[(position, value)] = int.from_bytes(chunk, "little")
    return result


def _empty_answer():
    return {"count": 0, "tokens": [], "witness": None}


def _decode_queries(job, names, nf, worlds, world_masks, theory_mask):
    queries = job["queries"]
    if not queries:
        return []

    def position(ref):
        return ref[0] * nf + names[ref[1]]

    needed = {}
    query_positions = []
    for query in queries:
        fixed_positions = []
        for binding in query["fixed"]:
            pos = position(binding["ref"])
            fixed_positions.append((pos, binding["value"]))
            needed.setdefault(pos, set()).add(binding["value"])
        query_positions.append((fixed_positions, position(query["target"])))

    fixed_masks = _fixed_value_masks(worlds, needed)
    answers = []
    for query, (fixed_positions, target_position) in zip(queries, query_positions):
        mask = theory_mask
        for pos, value in fixed_positions:
            mask &= fixed_masks[(pos, value)]
            if not mask:
                break
        if not mask:
            answers.append(_empty_answer())
            continue

        prefix = query["prefix"]
        prefix_length = len(prefix)
        count = 0
        witness = None
        next_digits = [False] * 10
        end_possible = False

        remaining = mask
        while remaining:
            lowest = remaining & -remaining
            world_index = lowest.bit_length() - 1
            spelling = str(worlds[world_index][target_position])
            if spelling.startswith(prefix):
                count += 1
                if witness is None:       # indices are visited ascending
                    witness = world_index
                if len(spelling) == prefix_length:
                    end_possible = True
                else:
                    next_digits[ord(spelling[prefix_length]) - 48] = True
            remaining ^= lowest

        if count == 0:
            answers.append(_empty_answer())
            continue
        tokens = [str(digit) for digit in range(10) if next_digits[digit]]
        if end_possible:
            tokens.append("END")
        answers.append({"count": count, "tokens": tokens, "witness": witness})
    return answers


# ---------------------------------------------------------------------------
# Public entry point.
# ---------------------------------------------------------------------------

def compile_job(job):
    fields = job["fields"]
    slots = job["slots"]
    names = {field["name"]: index for index, field in enumerate(fields)}
    nf = len(fields)

    # Flattened cell domains, slot-major then field order.  itertools.product
    # varies the last coordinate fastest, which is exactly the protocol's
    # mixed-radix lexicographic universe order.
    domains = [
        tuple(field["domain"])
        for _slot in range(slots)
        for field in fields
    ]
    world_count = prod(len(domain) for domain in domains)
    worlds = list(product(*domains))

    def flatten_window(window):
        return tuple(value for row in window for value in row)

    train_rows = [flatten_window(window) for window in job["train"]]
    predicates = [
        _compile_predicate(pred, names, nf, slots)
        for pred in job["predicates"]
    ]

    train_masks = _truth_masks(train_rows, predicates)
    world_masks = _truth_masks(worlds, predicates)

    rules = _discover_rules(
        len(predicates), job["width"], train_masks, world_masks,
        len(train_rows), world_count,
    )

    # Only clauses that were both discovered and operator-approved are active.
    # Rule order (length, then lexicographic IDs) is the required active order.
    approved = {tuple(clause) for clause in job["approved"]}
    active_rules = [rule for rule in rules if tuple(rule["clause"]) in approved]
    active = [rule["clause"] for rule in active_rules]

    # Joint effective theory: intersection of all active disjunctions.
    all_worlds = _all_ones(world_count)
    theory_mask = all_worlds
    clause_mask_cache = {}
    for rule in active_rules:
        clause_key = tuple(rule["clause"])
        clause_mask = clause_mask_cache.get(clause_key)
        if clause_mask is None:
            clause_mask = 0
            for literal in clause_key:
                clause_mask |= world_masks[literal]
            clause_mask_cache[clause_key] = clause_mask
        theory_mask &= clause_mask

    answers = _decode_queries(
        job, names, nf, worlds, world_masks, theory_mask
    )

    return {"rules": rules, "active": active, "answers": answers}
