"""Exact finite-domain compiler for the telemetry rule protocol.

The implementation deliberately works on the declared finite Cartesian universe.
Predicate truth is represented by Python integer bitsets: training windows use bit
position = training index, world windows use bit position = mixed-radix universe
index.  This makes the three discovery conditions (coverage, literal necessity and
non-tautology) direct exact operations.
"""
from __future__ import annotations

from itertools import product
from math import prod


# ---------------------------------------------------------------------------
# Compile the protocol's terms and predicates to compact evaluator records.
# ---------------------------------------------------------------------------

def _compile_term(term, names, nf):
    if "const" in term:
        return ("const", term["const"])
    if "sum" in term:
        return (
            "sum",
            tuple(ref[0] * nf + names[ref[1]] for ref in term["sum"]),
        )
    if "scale" in term:
        ref = term["ref"]
        return ("scale", term["scale"], ref[0] * nf + names[ref[1]])
    ref = term["ref"]
    return ("ref", ref[0] * nf + names[ref[1]])


def _compile_predicate(pred, names, nf, slots):
    if pred["kind"] == "cmp":
        return (
            "cmp",
            pred["op"],
            _compile_term(pred["left"], names, nf),
            _compile_term(pred["right"], names, nf),
        )
    field_ordinal = names[pred["field"]]
    positions = tuple(slot * nf + field_ordinal for slot in range(slots))
    return (pred["kind"], positions, pred["op"], pred["value"])


def _term_value(term, row):
    kind = term[0]
    if kind == "ref":
        return row[term[1]]
    if kind == "const":
        return term[1]
    if kind == "sum":
        total = 0
        for pos in term[1]:
            total += row[pos]
        return total
    # scale
    return term[1] * row[term[2]]


def _compare(left, op, right):
    if op == "eq":
        return left == right
    if op == "ne":
        return left != right
    if op == "lt":
        return left < right
    if op == "le":
        return left <= right
    if op == "gt":
        return left > right
    # ge
    return left >= right


def _predicate_true(pred, row):
    kind = pred[0]
    if kind == "cmp":
        return _compare(
            _term_value(pred[2], row), pred[1], _term_value(pred[3], row)
        )

    # Quantified any/all predicate.  ``positions`` has one entry per slot.
    op = pred[2]
    value = pred[3]
    if kind == "any":
        for pos in pred[1]:
            if _compare(row[pos], op, value):
                return True
        return False
    # all
    for pos in pred[1]:
        if not _compare(row[pos], op, value):
            return False
    return True


# ---------------------------------------------------------------------------
# Bitset construction.
# ---------------------------------------------------------------------------

def _truth_masks(rows, predicates):
    """Return one little-endian integer bitmask per predicate."""
    row_count = len(rows)
    byte_count = (row_count + 7) // 8
    chunks = [bytearray(byte_count) for _ in predicates]
    true_test = _predicate_true
    for index, row in enumerate(rows):
        byte_index = index >> 3
        bit = 1 << (index & 7)
        for p_index, pred in enumerate(predicates):
            if true_test(pred, row):
                chunks[p_index][byte_index] |= bit
    return [int.from_bytes(chunk, "little") for chunk in chunks]


def _lowest_set_bit_index(bits):
    return (bits & -bits).bit_length() - 1


def _all_ones(count):
    return (1 << count) - 1


# ---------------------------------------------------------------------------
# Exact discovery.
# ---------------------------------------------------------------------------

def _discover_rules(predicate_count, width, train_masks, world_masks,
                    train_count, world_count):
    """Enumerate every eligible clause and its two deterministic certificates.

    A clause is a disjunction.  Coverage over all training rows is monotone as
    literals are added, so recursive enumeration stops extending a clause as soon
    as its partial disjunction already covers every training row.  Such an
    extension can never satisfy literal-by-literal inclusion minimality.
    """
    all_training = _all_ones(train_count)
    all_worlds = _all_ones(world_count)
    max_len = min(width, predicate_count)
    rules = []
    empty = ()

    def examine(clause, covered):
        witnesses = []
        for literal in clause:
            others = 0
            for other in clause:
                if other != literal:
                    others |= train_masks[other]
            only_this = train_masks[literal] & ~others & all_training
            # ``covered == all_training`` ensures this is exactly condition 2;
            # nonetheless checking the bitmask is the canonical witness rule.
            if not only_this:
                return
            witnesses.append(_lowest_set_bit_index(only_this))

        world_union = 0
        for literal in clause:
            world_union |= world_masks[literal]
        falsifying = all_worlds & ~world_union
        if not falsifying:              # a domain tautology
            return

        rules.append({
            "clause": list(clause),
            "witnesses": witnesses,
            "counterexample": _lowest_set_bit_index(falsifying),
        })

    def extend(start, clause, covered):
        # No clause of this prefix can be extended to one of valid length.
        if len(clause) == max_len:
            return
        for literal in range(start, predicate_count):
            next_clause = clause + (literal,)
            next_covered = covered | train_masks[literal]
            if next_covered == all_training:
                examine(next_clause, next_covered)
                # Adding literals cannot repair inclusion minimality once a
                # proper prefix already covers every training window.
            else:
                extend(literal + 1, next_clause, next_covered)

    extend(0, empty, 0)
    rules.sort(key=lambda rule: (len(rule["clause"]), tuple(rule["clause"])))
    return rules


# ---------------------------------------------------------------------------
# Decoding helpers.
# ---------------------------------------------------------------------------

class _WorldGeometry:
    """Bit-pattern geometry of the declared mixed-radix universe.

    For coordinate ``pos`` and a range of domain ordinals ``[lo, hi)``, all
    matching world indices form a repeated contiguous bit pattern.  This lets
    fixed-value and target-prefix constraints be represented as bitsets without
    allocating a full bitset for every domain value.
    """

    __slots__ = (
        "domains", "world_count", "all_worlds", "low_span",
        "repeat_factor", "_range_cache", "_value_cache", "_prefix_cache",
    )

    def __init__(self, domains):
        from bisect import bisect_left  # local import keeps module startup tiny

        self.domains = domains
        world_count = prod(len(domain) for domain in domains)
        self.world_count = world_count
        self.all_worlds = _all_ones(world_count)

        # suffix[i] = product of domain sizes at positions >= i.
        suffix = [1] * (len(domains) + 1)
        for i in range(len(domains) - 1, -1, -1):
            suffix[i] = suffix[i + 1] * len(domains[i])

        self.low_span = [suffix[i + 1] for i in range(len(domains))]
        self.repeat_factor = []
        for position, domain in enumerate(domains):
            low = self.low_span[position]
            stride = len(domain) * low
            high_count = world_count // stride
            if high_count == 1:
                repeated = 1
            else:
                repeated = ((1 << world_count) - 1) // ((1 << stride) - 1)
            self.repeat_factor.append(repeated)

        self._range_cache = {}
        self._value_cache = {}
        self._prefix_cache = {}

    def ordinal_range_mask(self, position, low, high):
        """Worlds whose cell at ``position`` has a domain ordinal in [low, high)."""
        key = (position, low, high)
        cached = self._range_cache.get(key)
        if cached is not None:
            return cached
        if low >= high:
            mask = 0
        else:
            block = self.low_span[position]
            pattern = ((1 << ((high - low) * block)) - 1) << (low * block)
            mask = pattern * self.repeat_factor[position]
        self._range_cache[key] = mask
        return mask

    def value_mask(self, position, value):
        """Worlds where the flattened cell at ``position`` equals ``value``."""
        key = (position, value)
        cached = self._value_cache.get(key)
        if cached is not None:
            return cached
        from bisect import bisect_left

        domain = self.domains[position]
        ordinal = bisect_left(domain, value)
        if ordinal == len(domain) or domain[ordinal] != value:
            mask = 0
        else:
            mask = self.ordinal_range_mask(position, ordinal, ordinal + 1)
        self._value_cache[key] = mask
        return mask

    def prefix_mask(self, position, prefix):
        """Worlds whose target canonical decimal spelling starts with prefix."""
        key = (position, prefix)
        cached = self._prefix_cache.get(key)
        if cached is not None:
            return cached

        if prefix == "":
            mask = self.all_worlds
        elif prefix[0] == "0":
            # The only canonical spelling beginning with a zero is "0".
            mask = self.value_mask(position, 0) if prefix == "0" else 0
        else:
            from bisect import bisect_left

            domain = self.domains[position]
            prefix_value = int(prefix)
            power = 1
            mask = 0
            maximum = domain[-1]
            # A prefix of length L can match only numbers of length L..7.
            for total_length in range(len(prefix), 8):
                lower = prefix_value * power
                if lower > maximum:
                    break
                upper = (prefix_value + 1) * power
                low_ordinal = bisect_left(domain, lower)
                high_ordinal = bisect_left(domain, upper)
                if low_ordinal < high_ordinal:
                    mask |= self.ordinal_range_mask(
                        position, low_ordinal, high_ordinal
                    )
                power *= 10
        self._prefix_cache[key] = mask
        return mask

    def exact_spelling_mask(self, position, spelling):
        """Worlds whose target canonical spelling is exactly ``spelling``."""
        if spelling == "":
            return 0
        if spelling[0] == "0":
            if spelling != "0":
                return 0
            value = 0
        else:
            value = int(spelling)
        return self.value_mask(position, value)


def _empty_answer():
    return {"count": 0, "tokens": [], "witness": None}


def _decode_queries(job, names, nf, domains, theory_mask):
    queries = job["queries"]
    if not queries:
        return []

    geometry = _WorldGeometry(domains)

    def position(ref):
        return ref[0] * nf + names[ref[1]]

    answers = []
    for query in queries:
        mask = theory_mask
        for binding in query["fixed"]:
            pos = position(binding["ref"])
            mask &= geometry.value_mask(pos, binding["value"])
            if not mask:
                break
        if not mask:
            answers.append(_empty_answer())
            continue

        target_position = position(query["target"])
        prefix = query["prefix"]
        matching = mask & geometry.prefix_mask(target_position, prefix)
        if not matching:
            answers.append(_empty_answer())
            continue

        next_digits = []
        for digit in range(10):
            extension = mask & geometry.prefix_mask(
                target_position, prefix + str(digit)
            )
            if extension:
                next_digits.append(str(digit))
        end_possible = bool(
            mask & geometry.exact_spelling_mask(target_position, prefix)
        )
        if end_possible:
            next_digits.append("END")

        answers.append({
            "count": matching.bit_count(),
            "tokens": next_digits,
            "witness": _lowest_set_bit_index(matching),
        })
    return answers


# ---------------------------------------------------------------------------
# Public entry point.
# ---------------------------------------------------------------------------

def compile_job(job):
    fields = job["fields"]
    slots = job["slots"]
    names = {field["name"]: index for index, field in enumerate(fields)}
    nf = len(fields)

    # Flattened cell domains, slot-major then field order.  itertools.product
    # varies the last coordinate fastest, which is exactly the protocol's
    # mixed-radix lexicographic universe order.
    domains = [
        tuple(field["domain"])
        for _slot in range(slots)
        for field in fields
    ]
    world_count = prod(len(domain) for domain in domains)
    worlds = list(product(*domains))

    def flatten_window(window):
        return tuple(value for row in window for value in row)

    train_rows = [flatten_window(window) for window in job["train"]]
    predicates = [
        _compile_predicate(pred, names, nf, slots)
        for pred in job["predicates"]
    ]

    train_masks = _truth_masks(train_rows, predicates)
    world_masks = _truth_masks(worlds, predicates)

    rules = _discover_rules(
        len(predicates), job["width"], train_masks, world_masks,
        len(train_rows), world_count,
    )

    # Only clauses that were both discovered and operator-approved are active.
    # Rule order (length, then lexicographic IDs) is the required active order.
    approved = {tuple(clause) for clause in job["approved"]}
    active_rules = [rule for rule in rules if tuple(rule["clause"]) in approved]
    active = [rule["clause"] for rule in active_rules]

    # Joint effective theory: intersection of all active disjunctions.
    all_worlds = _all_ones(world_count)
    theory_mask = all_worlds
    clause_mask_cache = {}

clause_mask_cache = {}
for rule in active_rules:
    clause_key = tuple(rule["clause"])
    clause_mask = clause_mask_cache.get(clause_key)
    if clause_mask is None:
        clause_mask = 0
        for literal in clause_key:
            clause_mask |= world_masks[literal]
        clause_mask_cache[clause_key] = clause_mask
    theory_mask &= clause_mask

answers = _decode_queries(
    job, names, nf, domains, theory_mask
)

return {"rules": rules, "active": active, "answers": answers}

